/* Notebook Moon — SillyTavern extension, no external runtime dependencies */
(() => {
'use strict';
const context = () => SillyTavern.getContext();
const settings = () => { const c=context(); c.extensionSettings.notebook ??= {}; return c.extensionSettings.notebook; };
const save = () => context().saveSettingsDebounced();
const escapeHTML = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => 'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const st=settings(); st.pages??=[]; st.groups??=[]; st.pinnedGroups??=[];
const defaults={bg:'#273d79',cream:'#f7edc5',stroke:'#d5e3ff',highlight:'#7697ed',ink:'#101d43',opacity:35,brightness:100,wallpaper:''};
st.moonDesign={...defaults,...(st.moonDesign||{})};
let active='__favorites',editing=-1,search='',sort=false;
const menu=document.getElementById('extensionsMenu');
if(!menu) {console.error('Notebook: extensionsMenu not found');return;}
const trigger=document.createElement('div');trigger.id='openNotebookButton';trigger.className='list-group-item flex-container flexGap5 interactable';trigger.tabIndex=0;trigger.innerHTML='<i class="fa-solid fa-book-open"></i><span>Notebook</span>';menu.appendChild(trigger);
const host=document.createElement('div');host.id='notebookMoonRoot';host.className='nbm-hidden';document.body.appendChild(host);
const allGroups=()=>[...new Set([...st.groups,...st.pages.map(p=>p.group).filter(Boolean)])];
const count=g=>st.pages.filter(p=>p.group===g).length;
const favorite=p=>Boolean(p.moonFavorite);
const getList=()=>st.pages.map((p,i)=>({p,i})).filter(({p})=>active==='__favorites'?favorite(p):active==='__ungrouped'?!p.group:p.group===active).filter(({p})=>(p.title+' '+(p.content||'').replace(/<[^>]*>/g,' ')).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort?(a.p.title||'').localeCompare(b.p.title||'','ru'):a.i-b.i);
function markup(){
 const d=st.moonDesign;const groupList=[{name:'Избранное',key:'__favorites',count:st.pages.filter(favorite).length},...allGroups().map(g=>({name:g,key:g,count:count(g)})),{name:'Без папки',key:'__ungrouped',count:st.pages.filter(p=>!p.group).length}];
 host.innerHTML=`<div class="nbm-shell" style="--nbm-bg:${d.bg};--nbm-cream:${d.cream};--nbm-stroke:${d.stroke};--nbm-highlight:${d.highlight};--nbm-ink:${d.ink}"><div class="nbm-wallpaper"></div><div class="nbm-content"><button class="nbm-close" aria-label="Закрыть">×</button><header class="nbm-header"><div class="nbm-spark nbm-spark-left">✧</div><h1>Notes</h1><div class="nbm-spark nbm-spark-right">✧</div><div class="nbm-moons"><span>☾</span><span>◐</span><span>●</span><span>◑</span><span>☽</span></div></header><div class="nbm-main"><div class="nbm-folders-top"><button class="nbm-new-folder">＋ Новая папка</button><span></span><span></span><span></span></div><div class="nbm-folders">${groupList.map(g=>`<button class="nbm-folder ${active===g.key?'selected':''}" data-group="${escapeHTML(g.key)}"><span class="nbm-frame">${escapeHTML(g.name)}</span><span class="nbm-count">${g.count} ${g.count===1?'заметка':'заметок'}</span></button>`).join('')}</div><div class="nbm-divider"><span></span><b>✧ ✧ ✧ ✧ ✧ ✧ ✧</b><span></span></div><div class="nbm-section"><div class="nbm-section-top"><h2>${escapeHTML(active==='__favorites'?'Избранное':active==='__ungrouped'?'Без папки':active)}</h2><div class="nbm-actions"><button data-act="add" title="Добавить заметку">＋</button><button data-act="sort" title="Сортировать">↕</button><button data-act="search" title="Поиск">⌕</button></div></div><div class="nbm-search-row" ${search?'':'hidden'}><input id="nbm-search" placeholder="Поиск заметок" value="${escapeHTML(search)}"><button data-act="clearsearch">×</button></div><div class="nbm-notes">${getList().length?getList().map(({p,i},n)=>`<div class="nbm-note"><button class="nbm-note-open" data-open="${i}">${n+1}. ${escapeHTML(p.title||'Без названия')}</button><button class="nbm-fav ${favorite(p)?'on':''}" data-fav="${i}" title="Избранное">${favorite(p)?'★':'☆'}</button><button class="nbm-arrow" data-open="${i}" title="Открыть">→</button></div>`).join(''):'<p class="nbm-empty">Здесь пока нет заметок.</p>'}</div></div></div><button class="nbm-settings-button" title="Настройки" aria-label="Настройки"><i class="fa-solid fa-gear"></i></button></div><div class="nbm-editor" hidden><div class="nbm-editor-head"><button data-act="back">← Назад</button><div class="nbm-editor-actions"><button data-act="copy">Копировать</button><button data-act="togglefavorite">☆ Избранное</button><button data-act="save">Сохранить</button><button data-act="delete">Удалить</button></div></div><input class="nbm-edit-title" placeholder="Название заметки"><div class="nbm-toolbar"><button data-format="bold" title="Жирный"><b>B</b></button><button data-format="italic" title="Курсив"><i>I</i></button><button data-format="underline" title="Подчёркнутый"><u>U</u></button><button data-format="insertUnorderedList" title="Список">☷</button><button data-format="insertOrderedList" title="Нумерованный список">1.</button></div><div class="nbm-edit-body" contenteditable="true" role="textbox" aria-label="Текст заметки" data-placeholder="Начните писать заметку..."></div></div><div class="nbm-settings-backdrop" hidden><div class="nbm-settings-modal"><div class="nbm-modal-head"><h3>Настройки Notebook</h3><button data-act="closesettings">×</button></div><p>Обои всего блокнота — под всеми элементами интерфейса.</p><label class="nbm-file-label">Загрузить обои<input type="file" id="nbm-file" accept="image/*" hidden></label><button data-act="removewallpaper">Убрать обои</button><label>Прозрачность <output id="nbm-opacity-value">${d.opacity}%</output><input type="range" id="nbm-opacity" min="0" max="100" value="${d.opacity}"></label><label>Яркость <output id="nbm-brightness-value">${d.brightness}%</output><input type="range" id="nbm-brightness" min="10" max="200" value="${d.brightness}"></label><div class="nbm-colors">${[['bg','Фон'],['cream','Текст'],['stroke','Рамки'],['highlight','Линии']].map(([k,l])=>`<label>${l}<input type="color" data-color="${k}" value="${d[k]}"></label>`).join('')}</div></div></div></div>`;
 applyWallpaper();bind();
}
function applyWallpaper(){const d=st.moonDesign,wall=host.querySelector('.nbm-wallpaper');if(!wall)return;wall.style.backgroundImage=d.wallpaper?`url(${JSON.stringify(d.wallpaper)})`:'none';wall.style.opacity=d.opacity/100;wall.style.filter=`brightness(${d.brightness}%)`;}
function persist(){save();}
function openEditor(i){editing=i;const p=st.pages[i];if(!p)return;host.querySelector('.nbm-edit-title').value=p.title||'';host.querySelector('.nbm-edit-body').innerHTML=p.content||'';host.querySelector('.nbm-editor').hidden=false;host.querySelector('.nbm-shell').classList.add('nbm-editing');host.querySelector('.nbm-editor [data-act=togglefavorite]').textContent=favorite(p)?'★ Избранное':'☆ Избранное';}
function closeEditor(saveFirst=true){if(saveFirst&&editing>=0){st.pages[editing]={...st.pages[editing],title:host.querySelector('.nbm-edit-title').value.trim()||'Без названия',content:host.querySelector('.nbm-edit-body').innerHTML};persist();}editing=-1;markup();}
function copyText(t){navigator.clipboard?.writeText(t).catch(()=>fallbackCopy(t))??fallbackCopy(t);}
function fallbackCopy(t){const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();}
function bind(){
 host.querySelector('.nbm-close').onclick=()=>host.classList.add('nbm-hidden');
 host.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{active=b.dataset.group;search='';markup()});
 host.querySelector('.nbm-new-folder').onclick=()=>{const n=prompt('Название новой папки:')?.trim();if(!n)return;if(n==='Избранное'||allGroups().includes(n)){alert('Такая папка уже существует');return;}st.groups.push(n);active=n;persist();markup()};
 host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openEditor(+b.dataset.open));
 host.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{const p=st.pages[+b.dataset.fav];p.moonFavorite=!favorite(p);persist();markup()});
 host.querySelector('[data-act=add]').onclick=()=>{if(active==='__favorites'){alert('Выбери папку для новой заметки');return;}const p={title:'Новая заметка',content:'',group:active==='__ungrouped'?'':active};st.pages.push(p);persist();openEditor(st.pages.length-1)};
 host.querySelector('[data-act=sort]').onclick=()=>{sort=!sort;markup()};
 host.querySelector('[data-act=search]').onclick=()=>{const r=host.querySelector('.nbm-search-row');r.hidden=false;r.querySelector('input').focus()};
 host.querySelector('[data-act=clearsearch]').onclick=()=>{search='';markup()};
 host.querySelector('#nbm-search').oninput=e=>{const caret=e.target.selectionStart;search=e.target.value;const list=host.querySelector('.nbm-notes');list.innerHTML=getList().length?getList().map(({p,i},n)=>`<div class="nbm-note"><button class="nbm-note-open" data-open="${i}">${n+1}. ${escapeHTML(p.title||'Без названия')}</button><button class="nbm-fav ${favorite(p)?'on':''}" data-fav="${i}">${favorite(p)?'★':'☆'}</button><button class="nbm-arrow" data-open="${i}">→</button></div>`).join(''):'<p class="nbm-empty">Ничего не найдено</p>';list.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openEditor(+b.dataset.open));list.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{st.pages[+b.dataset.fav].moonFavorite=!favorite(st.pages[+b.dataset.fav]);persist();markup()});};
 host.querySelector('[data-act=back]').onclick=()=>closeEditor();host.querySelector('[data-act=save]').onclick=()=>closeEditor();
 host.querySelector('[data-act=delete]').onclick=()=>{if(editing<0||!confirm('Удалить эту заметку без возможности восстановления?'))return;st.pages.splice(editing,1);persist();editing=-1;markup()};
 host.querySelector('[data-act=togglefavorite]').onclick=()=>{if(editing<0)return;const p=st.pages[editing];p.moonFavorite=!favorite(p);persist();host.querySelector('[data-act=togglefavorite]').textContent=favorite(p)?'★ Избранное':'☆ Избранное'};
 host.querySelector('[data-act=copy]').onclick=()=>{const tmp=document.createElement('div');tmp.innerHTML=host.querySelector('.nbm-edit-body').innerHTML;copyText(tmp.innerText||tmp.textContent||'')};
 host.querySelectorAll('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{host.querySelector('.nbm-edit-body').focus();document.execCommand(b.dataset.format,false,null)}});
 host.querySelector('.nbm-settings-button').onclick=()=>host.querySelector('.nbm-settings-backdrop').hidden=false;
 host.querySelector('[data-act=closesettings]').onclick=()=>host.querySelector('.nbm-settings-backdrop').hidden=true;
 host.querySelector('.nbm-settings-backdrop').onclick=e=>{if(e.target.classList.contains('nbm-settings-backdrop'))e.target.hidden=true};
 host.querySelector('#nbm-file').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){alert('Выбери изображение');return;}if(f.size>3*1024*1024){alert('Изображение слишком большое. Выбери файл до 3 МБ.');return;}const reader=new FileReader();reader.onload=()=>{st.moonDesign.wallpaper=reader.result;persist();applyWallpaper()};reader.readAsDataURL(f)};
 host.querySelector('[data-act=removewallpaper]').onclick=()=>{st.moonDesign.wallpaper='';persist();applyWallpaper()};
 for(const k of ['opacity','brightness'])host.querySelector('#nbm-'+k).oninput=e=>{st.moonDesign[k]=+e.target.value;host.querySelector('#nbm-'+k+'-value').textContent=e.target.value+'%';applyWallpaper();persist()};
 host.querySelectorAll('[data-color]').forEach(el=>el.oninput=()=>{st.moonDesign[el.dataset.color]=el.value;host.querySelector('.nbm-shell').style.setProperty('--nbm-'+el.dataset.color,el.value);persist()});
}
trigger.onclick=()=>{host.classList.toggle('nbm-hidden');if(!host.classList.contains('nbm-hidden'))markup()};trigger.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();trigger.click()}};
markup();
try{context().registerSlashCommand?.('notebook',()=>trigger.click(),['nb'],'Toggle Notebook')}catch(e){}
})();
